from content.services import RAW as SERVICES, pairs

SV = {r["slug"]: r for r in SERVICES}


def helps(lst):
    out = []
    for slug, text in lst:
        s = SV[slug]
        out.append(("services/%s.html" % slug, s["icon"], s["name"], text))
    return out


